:root {
  --card-bg: #fdf8f0;
  --card-border: #d6c9a8;
  --header-bg: #2c2416;
  --brand-text: #f5e8c8;
  --badge-bg: #b87333;
  --badge-text: #fff8ee;
  --swatch-prussian: #1C3A5E;
  --swatch-oxblood: #6B1A1A;
  --swatch-verdigris: #3A7D6F;
  --swatch-amber: #B87333;
  --swatch-bg: #f0e8d8;
  --swatch-name: #2c2416;
  --swatch-code: #7a6a52;
  --prop-label: #5a4e3a;
  --prop-track: #e0d5c0;
  --prop-fill: #3A7D6F;
  --prop-fill-slow: #b87333;
  --footer-bg: #ede3ce;
  --footer-text: #5a4e3a;
  --price-text: #2c2416;
  --divider: #d6c9a8;
}

.ink-card {
  width: 460px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.ink-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
}

.ink-brand {
  color: var(--brand-text);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.ink-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}

.ink-swatches {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  padding: 16px;
  border-bottom: 1px solid var(--divider);
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin: 0;
}

.swatch-blob {
  width: 68px;
  height: 68px;
  border-radius: 50% 40% 55% 35% / 40% 55% 35% 50%;
  border: 2px solid var(--card-border);
}

.swatch-blob[data-color="prussian"] { background-color: var(--swatch-prussian); }
.swatch-blob[data-color="oxblood"]  { background-color: var(--swatch-oxblood); }
.swatch-blob[data-color="verdigris"]{ background-color: var(--swatch-verdigris); }
.swatch-blob[data-color="amber"]    { background-color: var(--swatch-amber); }

.swatch figcaption {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.swatch-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--swatch-name);
  text-align: center;
  line-height: 1.3;
}

.swatch-code {
  font-size: 10px;
  color: var(--swatch-code);
  font-weight: 400;
}

.ink-properties {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--divider);
}

.prop {
  display: flex;
  align-items: center;
  gap: 10px;
}

.prop-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--prop-label);
  width: 58px;
  flex-shrink: 0;
}

.prop-bar {
  flex: 1;
  height: 8px;
  background-color: var(--prop-track);
  border-radius: 4px;
  overflow: hidden;
}

.prop-fill {
  height: 100%;
  background-color: var(--prop-fill);
  border-radius: 4px;
}

.prop-fill--slow {
  background-color: var(--prop-fill-slow);
}

.ink-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
}

.ink-volume {
  font-size: 12px;
  color: var(--footer-text);
  font-weight: 400;
}

.ink-price {
  font-size: 18px;
  font-weight: 700;
  color: var(--price-text);
}
